    reg        clk;
    reg        load;
    reg [9:0]  data;
    wire       tc;

    // Track errors for self-checking
    integer    errors = 0;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk  (clk),
        .load (load),
        .data (data),
        .tc   (tc)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // Task to check output with `!==`
    task check_tc;
        input [0:0] expected_tc;
        begin
            @(posedge clk);
            #1; // small delay to sample after clock edge
            if (tc !== expected_tc) begin
                $display("Time %0t: Mismatch! data=%d, load=%b, tc=%b, expected_tc=%b", 
                         $time, data, load, tc, expected_tc);
                errors = errors + 1;
            end
        end
    endtask

    // 3. Stimulus & self-checking:
    initial begin
        // Initialize signals
        clk = 0;
        load = 0;
        data = 10'd0;

        // Wait for reset stabilization
        #12;

        // Test 1: Load 0, tc should immediately be 1 (or stay 1)
        @(posedge clk);
        load = 1;
        data = 10'd0;
        #1;
        if (tc !== 1'b1) begin
            $display("Time %0t: Load 0 failed tc check", $time);
            errors = errors + 1;
        end

        // Test 2: Load countdown value of 3
        @(posedge clk);
        load = 1;
        data = 10'd3;

        // Next cycle load=0, count goes from 3 to 2
        @(posedge clk);
        load = 0;
        // Expected tc at this point: count is 2 -> tc = 0
        #1;
        if (tc !== 1'b0) begin
            $display("Time %0t: Count=2 tc mismatch", $time);
            errors = errors + 1;
        end

        // Cycle 2 of countdown: count goes from 2 to 1
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin
            $display("Time %0t: Count=1 tc mismatch", $time);
            errors = errors + 1;
        end

        // Cycle 3 of countdown: count goes from 1 to 0
        @(posedge clk);
        #1;
        if (tc !== 1'b1) begin
            $display("Time %0t: Count=0 tc mismatch", $time);
            errors = errors + 1;
        end

        // Cycle 4: count stays at 0, tc stays 1
        @(posedge clk);
        #1;
        if (tc !== 1'b1) begin
            $display("Time %0t: Count staying at 0 tc mismatch", $time);
            errors = errors + 1;
        end

        // Test 3: Reload during countdown (interrupting)
        @(posedge clk);
        load = 1;
        data = 10'd2;

        @(posedge clk);
        load = 0; // count becomes 1, tc = 0
        #1;
        if (tc !== 1'b0) begin
            $display("Time %0t: Interrupt countdown tc=0 check failed", $time);
            errors = errors + 1;
        end

        // Load new value before reaching 0 (load 1)
        @(posedge clk);
        load = 1;
        data = 10'd1;

        @(posedge clk);
        load = 0; // count becomes 0, tc becomes 1
        #1;
        if (tc !== 1'b1) begin
            $display("Time %0t: Reloaded countdown reach 0 check failed", $time);
            errors = errors + 1;
        end

        // Extra cycles to let it settle
        #20;

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
